async getProducts(params: ProductParams): Promise<PaginatedResponse<Product>> {
  const queryParams = new URLSearchParams();

  if (params.page) queryParams.append('page', String(params.page));
  if (params.limit) queryParams.append('limit', String(params.limit));
  if (params.search) queryParams.append('search', params.search);
  if (params.categoryId) queryParams.append('categoryId', params.categoryId);
  if (params.minPrice) queryParams.append('minPrice', String(params.minPrice));
  if (params.maxPrice) queryParams.append('maxPrice', String(params.maxPrice));
  if (params.status) queryParams.append('status', params.status);

  const url = `/products?${queryParams.toString()}`;
  const response = await api.get(url);
  return response.data;
}
```

```typescript
async sendMessage(chatId: string, message: { content: string; type: 'text' | 'image' }): Promise<Message> {
  try {
    const response = await api.post(`/chats/${chatId}/messages`, message);
    return response.data;
  } catch (error) {
    // Si l'erreur est liée à la connexion, stocker le message dans une file d'attente offline
    if (error.message?.includes('Network Error')) {
      // Ajouter le message à la file d'attente offline
      await this.offlineQueue.enqueue('sendMessage', { chatId, message });
      throw new Error('Message enregistré. Il sera envoyé automatiquement lorsque la connexion sera rétablie.');
    }
    throw error;
  }
}
```

