async initiateDeposit(amount: number, operator: 'MTN' | 'ORANGE' | 'CAMTEL'): Promise<DepositInitiationResponse> {
  // Validation côté client
  if (amount < 100) {
    throw new Error('Le montant minimum de dépôt est 100 FCFA');
  }

  if (amount > 1000000) {
    throw new Error('Le montant maximum de dépôt est 1 000 000 FCFA');
  }

  try {
    const response = await api.post('/deposits/initiate', { amount, operator });
    return response.data;
  } catch (error) {
    if (error.response?.status === 400) {
      throw new Error('Les données de dépôt sont invalides. Vérifiez le montant et l\'opérateur.');
    }
    throw new Error('Une erreur est survenue lors de l\'initiation du dépôt');
  }
}
```
